# Perform BFS from start node, tracking depth
from collections import deque

start = "19f3cd308f"
target_depth = 6

# BFS to find nodes at exactly depth 6
queue = deque([(start, 0)])  # (node, depth)
visited = {start}
nodes_at_depth = {0: [start]}

while queue:
    node, depth = queue.popleft()

    if depth >= target_depth:
        continue

    for neighbor in graph.get(node, []):
        if neighbor not in visited:
            visited.add(neighbor)
            new_depth = depth + 1
            if new_depth not in nodes_at_depth:
                nodes_at_depth[new_depth] = []
            nodes_at_depth[new_depth].append(neighbor)
            queue.append((neighbor, new_depth))

print("Nodes at each depth:")
for d in sorted(nodes_at_depth.keys()):
    print(f"Depth {d}: {nodes_at_depth[d]}")

print(f"\nNodes at depth {target_depth}: {nodes_at_depth.get(target_depth, [])}")
```

